import{_ as t,o as i,c as n,ag as r}from"./chunks/framework.D5hoimZQ.js";const p=JSON.parse('{"title":"科学日报 · 2026-10-30（生物医学 / 肿瘤免疫 · 真核起源）","description":"","frontmatter":{"sidebar":true},"headers":[],"relativePath":"topics/biomedicine/science-daily-2026-10-30-biomed.md","filePath":"topics/biomedicine/science-daily-2026-10-30-biomed.md"}'),s={name:"topics/biomedicine/science-daily-2026-10-30-biomed.md"};function e(c,o,a,d,g,l){return i(),n("div",null,[...o[0]||(o[0]=[r('<h1 id="科学日报-·-2026-10-30-生物医学-肿瘤免疫-·-真核起源" tabindex="-1">科学日报 · 2026-10-30（生物医学 / 肿瘤免疫 · 真核起源） <a class="header-anchor" href="#科学日报-·-2026-10-30-生物医学-肿瘤免疫-·-真核起源" aria-label="Permalink to &quot;科学日报 · 2026-10-30（生物医学 / 肿瘤免疫 · 真核起源）&quot;">​</a></h1><blockquote><p>指向仓库：<code>ScienceDaily/daily/2026-10-30.md</code> — 第49期 ｜ 科学板块（2 篇） 落盘说明：文件名带 <code>-biomed</code> 后缀，避免与其它主题同日同名文件互引产生伪边（见 <code>topics/ai-brain/auto-link-quality-fixes.md</code>）。</p></blockquote><hr><h2 id="科学日报-2026-10-30-生物医学-·-1-2-肾癌「肿瘤组装体」——caf-经-wnt→activin-a-轴维持-cd8-t-干性、决定-pd-1-疗效" tabindex="-1">科学日报 2026-10-30（生物医学 · 1/2）：肾癌「肿瘤组装体」——CAF 经 WNT→activin A 轴维持 CD8⁺T 干性、决定 PD-1 疗效 <a class="header-anchor" href="#科学日报-2026-10-30-生物医学-·-1-2-肾癌「肿瘤组装体」——caf-经-wnt→activin-a-轴维持-cd8-t-干性、决定-pd-1-疗效" aria-label="Permalink to &quot;科学日报 2026-10-30（生物医学 · 1/2）：肾癌「肿瘤组装体」——CAF 经 WNT→activin A 轴维持 CD8⁺T 干性、决定 PD-1 疗效&quot;">​</a></h2><blockquote><p>指向仓库：<code>ScienceDaily/daily/2026-10-30.md</code> ｜ DOI: 10.1038/s41586-026-11208-w ｜ Nature (2026)</p></blockquote><ul><li>问题：肿瘤与微环境的动态互作决定癌症进展与疗效，但现有模型<strong>难以自由操纵多种细胞组分、难以解构复杂的肿瘤—基质互作</strong>。</li><li>方法：做出<strong>组合式、可拼装（mix-and-match）的肿瘤组装体（tumour assembloids）</strong>——条件性重建<strong>人肾细胞癌（RCC）<strong>的多种组分：癌细胞、<strong>癌相关成纤维细胞（CAF）</strong>、<strong>肿瘤浸润免疫细胞</strong>；再用</strong>基因工程肾癌组装体 + 人源化小鼠</strong>做机制验证。</li><li>结果（实测）： <ul><li>揭示 <strong>CAF 协调肿瘤细胞与 CD8⁺T 细胞互作</strong>、<strong>非细胞自主地（non-cell-autonomous）维持 CD8⁺T 细胞干性</strong>并<strong>驱动对 anti-PD-1 的应答</strong>的机制；</li><li>信号轴：<strong>肿瘤来源的 WNT</strong> 诱导 <strong>CAF 表达 activin A</strong> → <strong>增强 CD8⁺T 细胞干性与对 PD-1 阻断的敏感性</strong>；</li><li><strong>无应答者</strong>中存在一群<strong>对 WNT 无反应、不产 activin A 的 CAF</strong> → <strong>CD8⁺T 干性受损、治疗抵抗</strong>。</li></ul></li><li>洞察（对本库 <code>biomedicine</code> × <code>ai-brain</code>）： <ol><li><strong>「疗效异质性来自微环境里的『坏邻居』亚群」</strong> —— 同样是 PD-1 抑制剂，响应与否不只取决于 T 细胞，而取决于<strong>CAF 中有没有那批「WNT 无反应、不产 activin A」的亚群</strong>。判据：<strong>当同一疗法的应答高度异质时，先去微环境里找「决定性的细胞亚群」，而不是只在靶细胞里找差异。</strong></li><li><strong>「可拼装组装体 = 把微环境变成可控变量」</strong> —— 能拆能拼，才能<strong>单独加减一个细胞组分</strong>、做因果实验。这与外脑判据「<strong>当要研究『数据/环境如何影响结果』时，先让组成有可扫的轴</strong>」（10-29 工具使用缩放律 SynthAPI）跨域同构：<strong>先让系统可控，再谈因果。</strong></li><li><strong>一句话定位</strong>：把 <code>biomedicine</code> 的免疫治疗主线从「靶点/T 细胞」推进到「<strong>肿瘤—CAF—T 三细胞互作的信号轴 + 可拼装人源模型</strong>」。</li></ol></li></ul><hr><h2 id="科学日报-2026-10-30-生物医学-·-2-2-培养出最接近真核生物的太古菌——厌氧、肽降解、会伸出膜突起" tabindex="-1">科学日报 2026-10-30（生物医学 · 2/2）：培养出最接近真核生物的太古菌——厌氧、肽降解、会伸出膜突起 <a class="header-anchor" href="#科学日报-2026-10-30-生物医学-·-2-2-培养出最接近真核生物的太古菌——厌氧、肽降解、会伸出膜突起" aria-label="Permalink to &quot;科学日报 2026-10-30（生物医学 · 2/2）：培养出最接近真核生物的太古菌——厌氧、肽降解、会伸出膜突起&quot;">​</a></h2><blockquote><p>指向仓库：<code>ScienceDaily/daily/2026-10-30.md</code> ｜ DOI: 10.1038/s41586-026-11170-7 ｜ Nature (2026)</p></blockquote><ul><li>问题：真核生物起源被认为关联太古菌门 <strong>Promethearchaeota</strong>（原「Asgard 太古菌」），但此前培养到的代表<strong>与真核生物亲缘较远</strong>，真核起源仍有诸多未知。</li><li>方法：分离两株菌 <strong>HC1 与 SC1</strong>，属于<strong>与真核生物亲缘最近的分支 Heimdallarchaeia</strong>，分别生长于<strong>纯共培养</strong>与<strong>与产甲烷菌的三元培养</strong>中；配合<strong>比较基因组学</strong>。</li><li>结果（实测）： <ul><li>均为<strong>严格厌氧、互营（syntrophic）、降解肽类、嗜中温</strong>的太古菌；<strong>产生膜突起与囊泡，但缺乏持久的内膜结构</strong>；</li><li>所有 Promethearchaeota 分离株的行为<strong>聚焦于细胞构建与膜结构，而非分裂</strong>（与典型原核生物相反）；</li><li>反直觉点：HC1 带<strong>好氧生活相关基因（如细胞色素 c 氧化酶 Cox）</strong>，但共培养<strong>无法在（微）氧下生长</strong>；只有在<strong>好氧菌存在时</strong>才微氧生长 → 提示 <strong>Cox 用于「解毒氧气」，而非呼吸</strong>；比较基因组学表明，已研究的携带 Cox 的 Heimdallarchaeia 很可能<strong>都不呼吸氧</strong>。</li></ul></li><li>洞察（对本库 <code>biomedicine</code> × <code>ai-brain</code>）： <ol><li><strong>「基因的存在 ≠ 功能的方向」</strong> —— HC1 有 Cox（好氧呼吸的标志酶），却把它用于<strong>解氧毒</strong>而非呼吸。判据：<strong>别用「基因/组件是否在场」推断功能，要看它在什么条件下被调用、替系统解决了什么问题。</strong> 这与外脑 §8「<strong>外部信号 &gt; 自评分</strong>」同族——<strong>看实际作用，不看名义标签。</strong></li><li><strong>「起源跃迁是『结构陡变 + 生理跃迁』的复合事件」</strong> —— 作者提出的真核起源图景：太古菌祖先<strong>本就有厌氧、无持久内膜、有膜突起</strong>；真核化 = <strong>细胞结构陡变</strong> + <strong>从厌氧到（兼性）好氧的生理跃迁</strong>，且早期宿主—线粒体互作很可能发生在<strong>低氧</strong>条件下、部分由<strong>氧气解毒</strong>介导。判据：<strong>重大跃迁往往是「结构 + 生理」两条线同时跨过阈值，而非单一突变。</strong></li><li><strong>一句话定位</strong>：把 <code>biomedicine</code> 的内共生主线（<code>chloroplast-endosymbiosis.md</code>）上溯到<strong>真核起源</strong>——<strong>线粒体祖先的入驻，可能始于一次「氧气处理」上的互利，而非呼吸功能的分工。</strong></li></ol></li></ul><hr><blockquote><p>📎 关联主题：<code>topics/biomedicine/index.md</code> ｜ <code>topics/ai-brain/index.md</code> ｜ 第49期 科学板块</p></blockquote><p>关键词：科学日报第49期、肿瘤组装体 tumour assembloid、肾细胞癌 RCC、癌相关成纤维细胞 CAF、肿瘤浸润免疫细胞、人源化小鼠、非细胞自主、CD8 T 细胞干性、anti-PD-1、WNT、activin A、免疫检查点抑制剂、疗效异质性、无应答者、可拼装 mix-and-match、Heimdallarchaeia、Promethearchaeota、Asgard 太古菌、HC1 SC1、严格厌氧、互营 syntrophic、肽降解 peptidotrophic、膜突起、囊泡、无持久内膜结构、细胞色素c氧化酶 Cox、氧气解毒非呼吸、比较基因组学、真核起源 eukaryogenesis、内共生、厌氧到兼性好氧、低氧宿主线粒体互作</p><p>关联：<code>topics/biomedicine/index.md</code>、<code>topics/biomedicine/science-daily-2026-10-29-biomed.md</code>（MCT1 线粒体乳酸）、<code>topics/biomedicine/chloroplast-endosymbiosis.md</code>、<code>topics/paleontology/index.md</code>、<code>topics/ai-brain/index.md</code></p>',14)])])}const b=t(s,[["render",e]]);export{p as __pageData,b as default};
